-- Give isOdd a Succ branch calling isEven.
mutual {
  fn isEven(subterm n : Nat()) -> (b : Bool()) {
    match n : (b : Bool()) {
      Zero() => Yes();
      Succ(m) => isOdd(subterm m);
    }
  }
  fn isOdd(subterm n : Nat()) -> (b : Bool()) {
    match n : (b : Bool()) {
      Zero() => No();
    }
  }
}
let two = Succ(Succ(Zero()));
print isEven(two);
print isOdd(two);

